begin;
create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
update public.community_feature_controls set enabled=true where feature='discovery';
insert into auth.users(id,email) values('51000000-0000-4000-8000-000000000001','discover-a@mizyun.test'),('51000000-0000-4000-8000-000000000002','discover-b@mizyun.test');update public.profiles set birth_year=1990 where id::text like '51000000%';
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='51000000-0000-4000-8000-000000000001';select * from public.community_save_profile('discover_a','A','AA',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='51000000-0000-4000-8000-000000000002';select * from public.community_save_profile('discover_b','B','BB',null,true,true,'2026-09-30');
set local request.jwt.claim.sub='51000000-0000-4000-8000-000000000001';
select is((select jsonb_array_length(result->'profiles') from public.community_broader_discovery_rpc('search','{"prefix":"discover"}')),0,'Existing searchable consent does not widen audience');
select throws_ok($$select * from public.community_broader_discovery_rpc('search','{"prefix":"d"}')$$,'P0001','community_invalid_input','Short enumeration forbidden');
reset role;delete from public.community_broader_discovery_usage;set local role authenticated;set local request.jwt.claim.sub='51000000-0000-4000-8000-000000000002';select * from public.community_broader_discovery_rpc('preferences','{"enabled":true}');set local request.jwt.claim.sub='51000000-0000-4000-8000-000000000001';
select is((select jsonb_array_length(result->'profiles') from public.community_broader_discovery_rpc('search','{"prefix":"discover"}')),1,'Separately consenting member appears');
select throws_ok($$select * from public.community_broader_discovery_rpc('search','{"prefix":"discover"}')$$,'P0001','community_rate_limited','Repeated enumeration capped without storing query terms');
reset role;delete from public.community_broader_discovery_usage;insert into public.community_blocks(blocker_user_id,blocked_user_id) values('51000000-0000-4000-8000-000000000002','51000000-0000-4000-8000-000000000001');set local role authenticated;
select is((select jsonb_array_length(result->'profiles') from public.community_broader_discovery_rpc('search','{"prefix":"discover"}')),0,'Either-side block hides prefix result');
set local request.jwt.claim.sub='51000000-0000-4000-8000-000000000002';
reset role;update public.community_feature_controls set enabled=false where feature='discovery';set local role authenticated;
select lives_ok($$select * from public.community_broader_discovery_rpc('preferences','{"enabled":false}')$$,'Discovery opt-out survives switch off');
select is((select item->>'enabled' from public.community_export_page('broaderDiscoveryPreferences')),'false','Export contains only own current preference');
select throws_ok($$select * from public.community_broader_discovery_preferences$$,'42501',null,'Raw preference enumeration denied');
select * from finish();rollback;
